mapper.select:
select FBRI.BASE_RULE_ID baseRuleId, FBRI.EFF_DATE effDate, FBRI.RATE_TYPE rateType, FBRI.RATE*100 rate, FBRI.COEFFICIENT coefficient, FBRI.INDEX_ID indexId, FBRI.INDEX_SOURCE indexSource, FBRI.SPREAD_RATE*100 spreadRate, FBRI.RESET_TYPE resetType, PLP.PROD_STYLE prodStyle, PLP.TERM_MAX investmentCycle, FBRI.BASE_RULE_TYPE baseRuleType, FBRI.PUBLISH_TYPE publishType, FBRI.RATE_LOWER*100 rateLower, FBRI.RATE_LIMIT*100 rateLimit, FP.VDATE vdate, FBRI.FINPROD_ID finprodId from FIN_BASE_RULE_INFO FBRI, FIN_PRODUCT FP left join prd_layer_param PLP on FP.FINPROD_ID = PLP.FINPROD_ID where FBRI.FINPROD_ID = FP.FINPROD_ID and (FBRI.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} or PLP.P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR}) and FBRI.BRANCH = 0
AND FBRI.BASE_RULE_TYPE = #{baseRuleType,jdbcType=VARCHAR}
AND FBRI.PUBLISH_TYPE = #{publishType,jdbcType=VARCHAR}
and FBRI.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and (FBRI.EFF_DATE = FP.VDATE OR FP.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
